<template><view :class="['app-page',{dark}]"><ui-header title="明细" back/><view v-if="records.length" class="records"><view v-for="item in records" :key="item.id" class="record"><view><text>{{typeName(item.type)}}</text><text class="muted">{{displayDateTime(item.createdAt)}}</text><text class="muted">{{item.description}}</text></view><text :class="['amount',{income:Number(item.amount)>0}]">{{Number(item.amount)>0?'+':''}}{{Number(item.amount).toFixed(2)}}</text></view></view><ui-empty v-else title="没有相关的记录"/></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';export default{data(){return{dark:false,records:[]}},onShow(){this.dark=isDark();api.getWallet().then(data=>{this.records=data.records||[]}).catch(e=>uni.showToast({title:e.message||'明细加载失败，请重试',icon:'none'}))},methods:{typeName(type){return({admin_credit:'管理员增加余额',admin_debit:'管理员扣减余额',order_payment:'订单余额支付',order_refund:'订单退款',recharge:'充值入账',income_protected:'订单收益冻结',income_release:'服务收益入账',settlement_reversal:'退款结算冲正',receivable_recovery:'收入抵扣追偿',receivable_writeoff:'财务核销追偿',withdraw_frozen:'提现冻结',withdraw_approved:'提现审核通过',withdraw_rejected:'提现驳回退回',withdraw_auto_cancel:'提现自动取消',account_merge:'账号合并转入',income:'收益入账'})[type]||'其他资金变动'}}}</script>
<style scoped>.records{margin:24rpx 28rpx;border-radius:24rpx;background:var(--surface);overflow:hidden;box-shadow:var(--shadow-card)}.record{min-height:116rpx;padding:20rpx 26rpx;display:flex;align-items:center;border-bottom:1rpx solid var(--line)}.record>view{flex:1;display:flex;flex-direction:column;gap:8rpx}.record .muted{font-size:22rpx}.amount{color:var(--primary);font-size:28rpx;font-weight:800}.amount.income{color:#19b967}</style>
